// ================= vloeiende, procedurele bewegingen (v2) =================
const DEG = Math.PI / 180;
const sm = x => x <= 0 ? 0 : x >= 1 ? 1 : x * x * (3 - 2 * x);
const mix = (a, b, t) => Array.isArray(a) ? a.map((v, i) => v + (b[i] - v) * t) : a + (b - a) * t;
// periodieke Catmull-Rom-spline door [u, waarde]-punten (u van 0 tot 1, eerste punt op u=0)
function loopSpline(pts) {
  const n = pts.length, U = k => pts[((k % n) + n) % n][0] + Math.floor(k / n), Pv = k => pts[((k % n) + n) % n][1];
  return u => {
    u = ((u % 1) + 1) % 1; let i = 0; for (let j = 0; j < n; j++) if (pts[j][0] <= u) i = j;
    const s = (u - U(i)) / (U(i + 1) - U(i)), p0 = Pv(i - 1), p1 = Pv(i), p2 = Pv(i + 1), p3 = Pv(i + 2);
    const f = (a, b, c, d) => 0.5 * (2 * b + (-a + c) * s + (2 * a - 5 * b + 4 * c - d) * s * s + (-a + 3 * b - 3 * c + d) * s * s * s);
    return Array.isArray(p1) ? p1.map((_, k) => f(p0[k], p1[k], p2[k], p3[k])) : f(p0, p1, p2, p3);
  };
}
// gang (hardlopen/wandelen): voet op de grond loopt lineair naar achteren, zwaai via spline
function gait(o) {
  const st = o.stance, legLen = 0.87;
  // zwaaibaan [fase, [vooruit, hoogte boven grond]]: fase 0 = neerzetten
  const swing = loopSpline(o.swing);
  const py = loopSpline(o.pelvis); // bekkenhoogte over de cyclus (fase van linkerbeen)
  return (u) => {
    const P = py(u);
    const leg = (ph) => { ph = ((ph % 1) + 1) % 1; let z, h, toe;
      if (ph < st) { const t = ph / st; z = mix(o.zc, o.zt, t);
        if (o.flat) { const a = t < 0.12 ? mix(o.toeC, 0, sm(t / 0.12)) : t < 0.62 ? 0 : o.toeT * sm((t - 0.62) / 0.38); toe = a; h = o.gc + (a > 0 ? 0.13 * Math.sin(a * DEG) : 0.05 * Math.sin(-a * DEG)); }
        else { h = o.gc + (o.gt - o.gc) * sm((t - 0.55) / 0.45); toe = mix(o.toeC, o.toeT, sm((t - 0.5) / 0.5)); } }
      else { const v = swing(ph); z = v[0]; h = v[1]; toe = v[2] !== undefined ? [0, -Math.sin(v[2] * DEG), Math.cos(v[2] * DEG)] : o.toeT; }
      if (!Array.isArray(toe)) toe = [0, -Math.sin(toe * DEG), Math.cos(toe * DEG)];
      return { z, h, toe }; };
    const L = leg(u), R = leg(u + 0.5), base = o.y0 || 0;
    // voet in wereldcoördinaten (figuur loopt ter plekke)
    const foot = (q, s) => ['w', s * (o.fx || 0.1), base + q.h, q.z + (o.z0 || 0)];
    const arm = (ph) => { const c = Math.cos(2 * Math.PI * ph); // +1 = hand voor
      return ['c', mix(o.armB[0], o.armF[0], (c + 1) / 2), mix(o.armB[1], o.armF[1], (c + 1) / 2), mix(o.armB[2], o.armF[2], (c + 1) / 2)]; };
    const tw = Math.sin(2 * Math.PI * u);
    return { r: [0, base + P, o.z0 || 0], o: [o.lean, -tw * (o.yaw || 0), 0], s: [0, tw * (o.twist || 0), 0], h: [-o.lean * 0.8, 0, 0],
      lf: foot(L, 1), rf: foot(R, -1), ltoe: L.toe, rtoe: R.toe, lpk: [1, 0, 0.05], rpk: [1, 0, 0.05],
      lh: arm(u + 0.5), rh: arm(u), lpe: o.pe, rpe: o.pe };
  };
}

// romp in één rechte lijn (plank, opdrukken): schouderhoogte shY, enkels op hoogte anY bij z = zA
const SPAN = 1.335;
function prone(shY, zA = -0.95, anY = 0.13) {
  const th = Math.asin((shY - anY) / SPAN), U = [0, Math.sin(th), Math.cos(th)], zS = zA + SPAN * Math.cos(th);
  return { r: [0, shY - 0.425 * U[1], zS - 0.425 * U[2]], o: [90 - th / DEG, 0, 0], fb: ['p', 0, -0.95, 0.03], pk: [1, 0, 0], toe: [0, -0.92, 0.38], zS };
}
// op de knieën: schouder → knie in een rechte lijn, knieën op (0, 0.065, zK)
function kneel(shY, zK = -0.5) {
  const span = 0.905, th = Math.asin((shY - 0.065) / span), U = [0, Math.sin(th), Math.cos(th)], zS = zK + span * Math.cos(th);
  return { r: [0, shY - 0.425 * U[1], zS - 0.425 * U[2]], o: [90 - th / DEG, 0, 0], fb: ['m', 0.11, 0.075, zK - 0.425], pk: [1, 0, 0], toe: [0, -0.15, -1], zS };
}
